/**
 * Build-time content reader over public/data/ (generated by `npm run build:data`).
 * Pure Node (fs) with a module-level memo, so it works in Next server components and in tsx tests.
 * App code imports it through "@/content" (server-only); client components never touch it.
 */
import fs from "fs";
import path from "path";
import type { Lesson, GlossaryTerm, AcronymTerm, SimulatorMeta } from "@/types";
import type {
  Catalog,
  CatalogBook,
  CatalogGrade,
  CatalogPart,
  ExamsIndex,
  NavLesson,
  PartKey,
  PartManifest,
  PartRef,
} from "@/types/catalog";
import type { OfficialLessonAssessments } from "@/types/assessments";
import type { DeepChallengingQuestion } from "@/types/deep-questions";
import type { LessonStoryline } from "@/types/storyline";
import { toPartKey } from "./paths";

const DATA_ROOT = path.resolve(process.cwd(), "public", "data");
const memo = new Map<string, unknown>();

function read<T>(rel: string): T | null {
  if (memo.has(rel)) return memo.get(rel) as T | null;
  const file = path.join(DATA_ROOT, ...rel.split("/"));
  const value = fs.existsSync(file) ? (JSON.parse(fs.readFileSync(file, "utf8")) as T) : null;
  memo.set(rel, value);
  return value;
}

function mustRead<T>(rel: string): T {
  const value = read<T>(rel);
  if (value === null) throw new Error(`Missing generated data file public/data/${rel}. Run \`npm run build:data\`.`);
  return value;
}

// ── Catalog ────────────────────────────────────────────────────────────────

export function getCatalog(): Catalog {
  return mustRead<Catalog>("catalog.json");
}

export interface PartContext {
  grade: CatalogGrade;
  book: CatalogBook;
  part: CatalogPart;
}

export function listParts(status?: CatalogPart["status"]): PartContext[] {
  return getCatalog().grades.flatMap((grade) =>
    grade.books.flatMap((book) =>
      book.parts.filter((part) => !status || part.status === status).map((part) => ({ grade, book, part }))
    )
  );
}

export function findGrade(gradeId: string): CatalogGrade | null {
  return getCatalog().grades.find((g) => g.id === gradeId) ?? null;
}

export function findBook(gradeId: string, bookSlug: string): { grade: CatalogGrade; book: CatalogBook } | null {
  const grade = findGrade(gradeId);
  const book = grade?.books.find((b) => b.slug === bookSlug);
  return grade && book ? { grade, book } : null;
}

export function findPart(ref: PartRef): PartContext | null {
  return listParts().find((p) => p.part.key === toPartKey(ref)) ?? null;
}

/** The part that the pre-catalog URLs (/chapters/…, /exams/, …) belong to. */
export function getLegacyPartKey(): PartKey {
  const first = listParts("available")[0];
  if (!first) throw new Error("No available part in catalog");
  return first.part.key;
}

// ── Part content ───────────────────────────────────────────────────────────

export function getPartManifest(key: PartKey): PartManifest {
  return mustRead<PartManifest>(`${key}/manifest.json`);
}

export function findLessonRef(key: PartKey, chapterId: string, lessonSlug: string): NavLesson | null {
  const chapter = getPartManifest(key).chapters.find((c) => c.id === chapterId);
  return chapter?.lessons.find((l) => l.slug === lessonSlug) ?? null;
}

export function getLesson(key: PartKey, lessonId: string): Lesson | null {
  return read<Lesson>(`${key}/lessons/${lessonId}.json`);
}

export function getLessonNav(key: PartKey, lessonId: string): { prev?: NavLesson; next?: NavLesson } {
  const all = getPartManifest(key).chapters.flatMap((c) => c.lessons);
  const i = all.findIndex((l) => l.id === lessonId);
  return { prev: i > 0 ? all[i - 1] : undefined, next: i >= 0 && i < all.length - 1 ? all[i + 1] : undefined };
}

export function getCompanionLessons(key: PartKey, companionSlug: string): OfficialLessonAssessments[] {
  const companion = getPartManifest(key).companions.find((c) => c.slug === companionSlug);
  return (companion?.lessons ?? [])
    .map((l) => read<OfficialLessonAssessments>(`${key}/${companionSlug}/${l.lessonId}.json`))
    .filter((x): x is OfficialLessonAssessments => x !== null);
}

export function getCompanionLesson(key: PartKey, companionSlug: string, lessonId: string): OfficialLessonAssessments | null {
  return read<OfficialLessonAssessments>(`${key}/${companionSlug}/${lessonId}.json`);
}

export function getDeepQuestions(key: PartKey, lessonKey: string): DeepChallengingQuestion[] {
  return read<DeepChallengingQuestion[]>(`${key}/deep/${lessonKey}.json`) ?? [];
}

export function getGlossary(key: PartKey): GlossaryTerm[] {
  return read<GlossaryTerm[]>(`${key}/glossary.json`) ?? [];
}

export function getAcronyms(key: PartKey): AcronymTerm[] {
  return read<AcronymTerm[]>(`${key}/acronyms.json`) ?? [];
}

export function getSimulators(key: PartKey): SimulatorMeta[] {
  return read<SimulatorMeta[]>(`${key}/simulators.json`) ?? [];
}

/** Simulators attached to a lesson: by lesson number first, then by the lesson's simulatorId. */
export function getSimulatorsForLesson(key: PartKey, lesson: Pick<Lesson, "number" | "simulatorId">): SimulatorMeta[] {
  const all = getSimulators(key);
  const byNumber = all.filter((s) => s.lessonNumber === lesson.number);
  if (byNumber.length > 0) return byNumber;
  return lesson.simulatorId ? all.filter((s) => s.id === lesson.simulatorId) : [];
}

export function getStoryline(key: PartKey, lessonId: string): LessonStoryline | null {
  return read<LessonStoryline>(`${key}/storylines/${lessonId}.json`);
}

export function getExamsIndex(key: PartKey): ExamsIndex {
  return mustRead<ExamsIndex>(`${key}/exams-index.json`);
}

// ── generateStaticParams helpers ───────────────────────────────────────────

type PartParams = { gradeId: string; bookSlug: string; partId: string };

const availableParts = () => listParts("available");
const partParams = ({ part }: PartContext): PartParams => {
  const [gradeId, bookSlug, partId] = part.key.split("/");
  return { gradeId, bookSlug, partId };
};

export const staticParams = {
  grades: () => getCatalog().grades.map((g) => ({ gradeId: g.id })),
  books: () => getCatalog().grades.flatMap((g) => g.books.map((b) => ({ gradeId: g.id, bookSlug: b.slug }))),
  parts: () => availableParts().map(partParams),
  chapters: () =>
    availableParts().flatMap((p) =>
      getPartManifest(p.part.key).chapters.map((c) => ({ ...partParams(p), chapterId: c.id }))
    ),
  lessons: () =>
    availableParts().flatMap((p) =>
      getPartManifest(p.part.key).chapters.flatMap((c) =>
        c.lessons.map((l) => ({ ...partParams(p), chapterId: c.id, lessonSlug: l.slug }))
      )
    ),
  storylines: () =>
    availableParts().flatMap((p) => {
      const manifest = getPartManifest(p.part.key);
      const ids = new Set(manifest.storylineLessonIds);
      return manifest.chapters.flatMap((c) =>
        c.lessons.filter((l) => ids.has(l.id)).map((l) => ({ ...partParams(p), chapterId: c.id, lessonSlug: l.slug }))
      );
    }),
  companions: () =>
    availableParts().flatMap((p) =>
      getPartManifest(p.part.key)
        .companions.filter((c) => c.status === "available")
        .map((c) => ({ ...partParams(p), companionSlug: c.slug }))
    ),
  companionChapters: () =>
    availableParts().flatMap((p) =>
      getPartManifest(p.part.key)
        .companions.filter((c) => c.status === "available")
        .flatMap((c) =>
          [...new Set(c.lessons.map((l) => l.chapterId))].map((chapterId) => ({ ...partParams(p), companionSlug: c.slug, chapterId }))
        )
    ),
  companionLessons: () =>
    availableParts().flatMap((p) =>
      getPartManifest(p.part.key)
        .companions.filter((c) => c.status === "available")
        .flatMap((c) =>
          c.lessons.map((l) => ({ ...partParams(p), companionSlug: c.slug, chapterId: l.chapterId, lessonSlug: l.slug }))
        )
    ),
};

export function getNavCatalog(): import("@/types/catalog").NavCatalog {
  return {
    grades: getCatalog().grades.map((g) => ({
      id: g.id,
      title: g.title,
      books: g.books.map((b) => ({
        slug: b.slug,
        title: b.title,
        parts: b.parts.map((p) => ({ id: p.id, key: p.key, shortTitle: p.shortTitle, status: p.status })),
      })),
    })),
  };
}
